) as v(id, url, who)
where c.id = v.id;

select count(*) filter (where image_url like '%pexels%')     as pexels,
       count(*) filter (where image_url like '%wikimedia%')  as 위키백과_남음,
       count(*) filter (where image_url is null)             as 사진없음,
       count(*)                                              as 전체
  from public.cities;
